export type SiteStatus = 'up' | 'down' | 'unknown';

export interface MonitoredSite {
  id: string;
  user_id: string;
  name: string;
  url: string;
  check_interval_s: 300 | 900 | 3600;
  is_active: boolean;
  last_status: SiteStatus;
  last_checked_at: string | null;
  created_at: string;
}

export interface MonitorCheck {
  id: string;
  site_id: string;
  checked_at: string;
  is_up: boolean;
  status_code: number | null;
  response_ms: number;
  error_message: string | null;
  page_url?: string | null;
  screenshot_path?: string | null;
  evidence?: Record<string, unknown>;
}

export interface Incident {
  id: string;
  site_id: string;
  started_at: string;
  resolved_at: string | null;
  title?: string | null;
  severity?: 'info' | 'low' | 'medium' | 'high' | 'critical';
  root_cause: string | null;
  page_url?: string | null;
  screenshot_path?: string | null;
  evidence?: Record<string, unknown>;
  diagnosis?: {
    summary?: string;
    root_cause?: string | null;
    reproduction_steps?: string[];
    fix_suggestion?: string | null;
    severity?: string;
  };
  reproduction_steps?: string[];
  fix_suggestion?: string | null;
  verified_at?: string | null;
}

export interface AlertChannel {
  id: string;
  user_id: string;
  site_id: string | null;
  channel_type: 'email' | 'webhook';
  config: { email?: string; url?: string };
  is_active: boolean;
  created_at: string;
}

export interface MonitoredSiteWithLatestCheck extends MonitoredSite {
  latest_check: MonitorCheck | null;
}

export interface CreateSiteInput {
  name: string;
  url: string;
  interval_minutes?: 5 | 15 | 60;
  check_interval_s?: 300 | 900 | 3600;
}

export interface CreateAlertChannelInput {
  site_id?: string | null;
  channel_type: 'email' | 'webhook';
  config: { email?: string; url?: string };
}